@register.simple_tag
def icon(name, class_name=""):
    """Returns SVG icon HTML by name. Usage: {% icon 'dashboard' 'w-5 h-5' %}"""
    svg = ICONS.get(name, '')
    svg = svg.replace('width="22" height="22"', 'width="18" height="18"')
    if class_name:
        svg = svg.replace('class="icon"', f'class="icon {class_name}"')
    return mark_safe(svg)

@register.simple_tag
def icon_btn(name, text, class_name="btn btn-primary"):
    """Returns a button with icon. Usage: {% icon_btn 'add' 'Ajouter' 'btn btn-primary' %}"""
    svg = ICONS.get(name, '')
    return mark_safe(f'<button class="{class_name}">{svg} {text}</button>')